/// The fixed bytes at one site, when every stock node of the class agrees.
#[must_use]
pub fn fixed(class: u32, offset: usize) -> Option<&'static [u8]> {
    FIXED
        .iter()
        .find(|(site_class, site_offset, _)| *site_class == class && *site_offset == offset)
        .map(|(_, _, value)| *value)
}
